{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Membership — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfa;--accent:#6b956b;--muted:#6b6b6b;--card:#ffffff;--glass:rgba(255,255,255,0.7)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;background:var(--bg);color:#102;line-height:1.45}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:linear-gradient(180deg,rgba(255,255,255,0.9),rgba(255,255,255,0.6));backdrop-filter:blur(6px);position:sticky;top:0;z-index:10}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#8ab48a);display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none;font-weight:600}
    main{max-width:1100px;margin:36px auto;padding:28px}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:22px;align-items:center}
    .hero h1{margin:0;font-size:28px;color:#0e2b1f}
    .hero p{color:var(--muted)}
    .card{background:var(--card);border-radius:12px;padding:18px;box-shadow:0 6px 20px rgba(8,10,12,0.06)}
    .flex{display:flex;gap:12px;align-items:center}
    .plans{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}
    .plan{padding:16px;border-radius:10px;border:1px solid #e9efe9}
    .plan h3{margin:0 0 6px 0}
    .price{font-size:20px;color:var(--accent);font-weight:700}
    .muted{color:var(--muted);font-size:13px}
    label{display:block;font-weight:600;margin:8px 0 6px}
    input[type=text],select,input[type=number]{width:100%;padding:8px;border-radius:8px;border:1px solid #e6efe6}
    button.primary{background:var(--accent);color:white;border:0;padding:10px 14px;border-radius:10px;font-weight:700}
    .blend-output{margin-top:12px;padding:12px;border-left:3px solid #d9efd9;background:linear-gradient(180deg,rgba(250,255,250,0.9),white);border-radius:6px}
    footer{max-width:1100px;margin:36px auto;padding:18px;color:var(--muted)}
    .pattern{position:absolute;right:0;top:0;width:320px;height:320px;opacity:0.12;pointer-events:none;background-image:url('assets/img/pattern.svg');background-size:cover}
    .faq{margin-top:18px}
    .cta{display:flex;gap:10px;align-items:center;margin-top:18px}
    @media (max-width:880px){.hero{grid-template-columns:1fr;}.plans{grid-template-columns:1fr}.pattern{display:none}}
  </style>
</head>
<body>
  <div class="pattern" aria-hidden></div>
  <header>
    <div class="brand">
      <div class="logo">A</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">Careful aromatics that may support day-to-day balance</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Welcome</a>
      <a href="services.html">Sessions</a>
      <a href="blends.html">Blends</a>
      <a href="shop.html">Shop</a>
      <a href="pricing.html" style="color:var(--accent)">Membership</a>
      <a href="about.html">About</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div>
        <h1>Memberships built around rhythms, not routines</h1>
        <p class="muted">Join a supportive circle for thoughtfully blended fragrance, monthly guidance, and easy scent tools that may support calmer minutes and clearer attention.</p>
        <div class="card">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div>
              <div style="font-size:13px;color:var(--muted)">Current offer</div>
              <div style="font-weight:700">Essence Circle — first month on us</div>
            </div>
            <div class="price">From $18 / mo</div>
          </div>
          <div class="cta">
            <a class="primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a href="about.html" style="color:var(--muted);text-decoration:none;align-self:center">Learn more</a>
          </div>
        </div>

        <div class="plans">
          <div class="plan card">
            <h3>Seed — Starter</h3>
            <div class="price">$18 / mo</div>
            <div class="muted">Monthly single-blend kit + 10% shop discount</div>
            <ul style="padding-left:16px;margin-top:8px;color:var(--muted)">
              <li>One 10 mL blend crafted to a chosen vibe</li>
              <li>Monthly short scent ritual</li>
            </ul>
          </div>

          <div class="plan card">
            <h3>Circle — Core</h3>
            <div class="price">$38 / mo</div>
            <div class="muted">Two blends, member portal access, 15% discount</div>
            <ul style="padding-left:16px;margin-top:8px;color:var(--muted)">
              <li>Choice of blends each month</li>
              <li>Blend builder access + archive</li>
            </ul>
          </div>

          <div class="plan card">
            <h3>Care Bundle — Quarterly</h3>
            <div class="price">$99 / quarter</div>
            <div class="muted">Curated seasonal blends and a guided mini-course</div>
            <ul style="padding-left:16px;margin-top:8px;color:var(--muted)">
              <li>Three seasonal blends + planning guide</li>
            </ul>
          </div>
        </div>
      </div>

      <aside class="card">
        <h3 style="margin-top:0">Blend Builder — try a safe starter</h3>
        <p class="muted">Pick a mood and we suggest a simple, safe dilution and a small blend card you can write down. Not medical advice — for aromatherapy support only.</p>

        <label for="vibe">Vibe</label>
        <select id="vibe">
          <option value="calm">Calm & Grounded</option>
          <option value="clarity">Clarity & Focus</option>
          <option value="uplift">Uplift & Joy</option>
          <option value="rest">Rest & Sleep</option>
        </select>

        <label for="size">Carrier bottle size (mL)</label>
        <input id="size" type="number" value="10" min="5" max="100">

        <label for="dilution">Dilution strength</label>
        <select id="dilution">
          <option value="1">1% — very mild (recommended)</option>
          <option value="2">2% — gentle</option>
          <option value="3">3% — moderate</option>
        </select>

        <div style="margin-top:10px;display:flex;gap:8px">
          <button class="primary" id="buildBtn">Create blend</button>
          <button id="resetBtn" style="padding:10px;border-radius:8px;border:1px solid #e6efe6;background:white">Reset</button>
        </div>

        <div id="blendResult" class="blend-output" aria-live="polite" style="display:none"></div>

        <div style="margin-top:12px;font-size:13px;color:var(--muted)">
          Always do a patch test. Avoid use in pregnancy without professional input. Keep blends away from pets' faces; some oils are not pet-safe. See FAQ below.
        </div>
      </aside>
    </section>

    <section class="card faq">
      <h3 style="margin-top:0">FAQs — safety quick notes</h3>
      <ul>
        <li><strong>Patch test:</strong> Apply a small diluted sample to forearm for 24 hours; stop if irritation develops.</li>
        <li><strong>Pregnancy & medications:</strong> Some oils are best avoided; consult a qualified practitioner before use.</li>
        <li><strong>Pets:</strong> Certain oils (e.g., tea tree, pennyroyal) can be harmful to animals; keep blends out of reach and avoid direct application to pets.</li>
        <li><strong>Storage:</strong> Keep blends in dark glass, cool and away from direct heat or sunlight.</li>
      </ul>
    </section>

  </main>

  <footer>
    <div style="display:flex;justify-content:space-between;align-items:center">
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div class="muted">{{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </div>
      <div class="muted">Membership questions? <a href="contact.html">Connect</a></div>
    </div>
  </footer>

  <script>
    // Blend builder logic
    const vibes = {
      calm: {name:'Calm & Grounded', oils:[{name:'Lavender',drops:0.5},{name:'Cedarwood',drops:0.3},{name:'Bergamot',drops:0.2}]},
      clarity: {name:'Clarity & Focus', oils:[{name:'Rosemary',drops:0.45},{name:'Sweet Orange',drops:0.35},{name:'Peppermint',drops:0.2}]},
      uplift: {name:'Uplift & Joy', oils:[{name:'Sweet Orange',drops:0.6},{name:'Grapefruit',drops:0.25},{name:'Ylang Ylang',drops:0.15}]},
      rest: {name:'Rest & Sleep', oils:[{name:'Lavender',drops:0.7},{name:'Roman Chamomile',drops:0.2},{name:'Vetiver',drops:0.1}]}
    };

    function computeDrops(mL,percentRatio) {
      // Convert: approx 20 drops per mL carrier. drops = mL * (percent/100) * 20
      return Math.max(1, Math.round(mL * (percentRatio/100) * 20));
    }

    function buildBlend() {
      const vibeKey = document.getElementById('vibe').value;
      const size = Math.max(5, Number(document.getElementById('size').value) || 10);
      const dilution = Number(document.getElementById('dilution').value) || 1;
      const info = vibes[vibeKey];
      const totalDrops = computeDrops(size,dilution);

      // Distribute drops by relative weights
      const proportions = info.oils.map(o=>o.drops);
      const sum = proportions.reduce((s,n)=>s+n,0);
      const breakdown = info.oils.map((oil,i)=>{
        const ratio = proportions[i]/sum;
        return {name:oil.name,drops:Math.max(1,Math.round(ratio*totalDrops))};
      });

      const resultEl = document.getElementById('blendResult');
      resultEl.style.display='block';
      resultEl.innerHTML = '';

      const title = document.createElement('div');
      title.innerHTML = '<strong>'+info.name+'</strong> — '+dilution+'% in '+size+' mL carrier';
      resultEl.appendChild(title);

      const ul = document.createElement('ul');
      ul.style.margin='8px 0 6px 18px';
      ul.style.color='var(--muted)';
      breakdown.forEach(b=>{
        const li = document.createElement('li');
        li.textContent = b.name + ': ' + b.drops + ' drops';
        ul.appendChild(li);
      });
      resultEl.appendChild(ul);

      const card = document.createElement('div');
      card.style.marginTop='8px';
      card.style.padding='8px';
      card.style.border='1px dashed #e6efe6';
      card.style.borderRadius='8px';
      card.innerHTML = '<div style="font-weight:700;margin-bottom:6px">Blend Card</div>'+
        '<div style="font-size:14px;color:var(--muted)"><strong>Name:</strong> '+info.name+' Starter Mix</div>'+
        '<div style="font-size:14px;color:var(--muted)"><strong>Usage:</strong> Dilute in carrier as shown. Use 1–2 drops on a diffuser pad or 3–4 drops in a personal inhaler. Avoid direct skin contact without patch test.</div>';
      resultEl.appendChild(card);

      const note = document.createElement('div');
      note.style.marginTop='10px';
      note.style.fontSize='12px';
      note.style.color='var(--muted)';
      note.innerHTML = '<strong>Safety:</strong> This is a non-medical suggestion. Do a patch test. Not all oils are suitable for pregnancy, young children, or pets.';
      resultEl.appendChild(note);
    }

    document.getElementById('buildBtn').addEventListener('click', buildBlend);
    document.getElementById('resetBtn').addEventListener('click', ()=>{document.getElementById('blendResult').style.display='none';document.getElementById('size').value='10';document.getElementById('dilution').value='1';});
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fffaf8;--accent:#7a8f6f;--muted:#59615a}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial;color:#0b1a12;background:var(--bg)}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 26px;background:rgba(255,255,255,0.6);backdrop-filter:blur(4px)}
    .logo{display:flex;gap:12px;align-items:center}
    .logo .mark{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,var(--accent),#a0c79a);display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    main{max-width:980px;margin:28px auto;padding:20px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .card{background:white;border-radius:14px;padding:18px;box-shadow:0 8px 24px rgba(10,12,10,0.04)}
    h1{margin-top:0}
    .muted{color:var(--muted)}
    .try{margin-top:12px}
    .btn{background:var(--accent);color:white;padding:10px 14px;border-radius:10px;border:0;font-weight:700}
    footer{max-width:980px;margin:18px auto;padding:10px;color:var(--muted)}
    @media (max-width:900px){.grid{grid-template-columns:1fr}.pattern{display:none}}
  </style>
</head>
<body>
  <header>
    <div class="logo">
      <div class="mark">A</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">Thoughtful aromatics that may support clearer days</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Welcome</a>
      <a href="services.html">Sessions</a>
      <a href="blends.html">Blends</a>
      <a href="shop.html">Shop</a>
      <a href="pricing.html">Membership</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <div class="grid">
      <div>
        <div class="card">
          <h1>Careful scent work, guided by experience</h1>
          <p class="muted">We combine plant wisdom, safety-first formulation, and short guided rituals to create approachable scent practices that may support everyday calm and clarity. Our approach is gentle, research-informed, and designed to fit into small windows of your day.</p>

          <h3 style="margin-top:18px">How we work</h3>
          <ol class="muted">
            <li>Listen — a short intake to understand needs and preferences.</li>
            <li>Design — a simple blend with clear dilution guidance.</li>
            <li>Guide — a short scent practice you can repeat at home.</li>
          </ol>

          <div style="margin-top:14px">
            <strong>Real support, not promises.</strong> Our blends and rituals may support better focus, ease, or rest for some people. We do not offer medical diagnosis or treatment.
          </div>

          <div class="try">
            <button class="btn" id="tryBtn">Try a short guided exercise</button>
            <div style="margin-top:8px;font-size:13px;color:var(--muted)">A simple breath + intention practice, about 3 minutes.</div>
          </div>
        </div>

        <div class="card" style="margin-top:16px">
          <h3>Credentials & care</h3>
          <p class="muted">Our practitioner(s) have formal aromatherapy training and follow safety guidelines for dilution, contraindications, and client care. We ask about pregnancy, medications, and pets during consultations to keep recommendations safe and personalized.</p>
        </div>
      </div>

      <aside class="card">
        <h3>Quick details</h3>
        <p class="muted"><strong>Phone:</strong> <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p class="muted"><strong>Email:</strong> <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        <p class="muted"><strong>Location:</strong> {{CITY}}, {{STATE}}</p>
        <p style="margin-top:12px"><a href="book.html" class="btn" style="text-decoration:none;display:inline-block">Reserve a session</a></p>
      </aside>
    </div>
  </main>

  <footer>
    <div class="muted">If you have specific health concerns, consult an appropriate health professional. Our offerings may support wellbeing but are not a substitute for medical care.</div>
  </footer>

  <!-- Guided Exercise Modal (Pure JS) -->
  <div id="modal" role="dialog" aria-modal="true" aria-hidden="true" style="display:none;position:fixed;inset:0;background:rgba(10,12,10,0.4);align-items:center;justify-content:center;padding:20px">
    <div id="modalCard" style="max-width:720px;width:100%;background:white;border-radius:12px;padding:20px;box-shadow:0 12px 40px rgba(0,0,0,0.2)">
      <h2 id="modalTitle">Scent & Breath — short practice</h2>
      <div id="modalBody" style="color:var(--muted);margin-top:8px">Find a comfortable seat. This practice walks you through calming breaths and a journaling prompt.</div>
      <div style="margin-top:12px;display:flex;gap:8px;align-items:center">
        <button id="startBtn" class="btn">Start 3-minute practice</button>
        <button id="closeBtn" style="padding:8px;border-radius:8px;border:1px solid #e6efe6;background:white">Close</button>
      </div>
      <div id="progress" style="margin-top:14px;display:none">
        <div id="stepText" style="font-weight:700"></div>
        <div id="timer" style="font-size:18px;color:var(--muted);margin-top:6px"></div>
        <div style="margin-top:8px;color:var(--muted);font-size:13px">Tip: lightly inhale the chosen scent on a tissue, or just use your breath.</div>
      </div>
    </div>
  </div>

  <script>
    // Modal and guided exercise logic
    const modal = document.getElementById('modal');
    const modalCard = document.getElementById('modalCard');
    const tryBtn = document.getElementById('tryBtn');
    const closeBtn = document.getElementById('closeBtn');
    const startBtn = document.getElementById('startBtn');
    const progress = document.getElementById('progress');
    const stepText = document.getElementById('stepText');
    const timer = document.getElementById('timer');

    tryBtn.addEventListener('click', ()=>{modal.style.display='flex';modal.setAttribute('aria-hidden','false');});
    closeBtn.addEventListener('click', ()=>{modal.style.display='none';modal.setAttribute('aria-hidden','true');stopTimers();});

    let tId = null; let step = 0; let seconds = 0;
    function stopTimers(){clearInterval(tId);tId=null;progress.style.display='none';startBtn.disabled=false;}

    startBtn.addEventListener('click', ()=>{
      startBtn.disabled=true;progress.style.display='block';step=0;advance();
    });

    function advance(){
      // Sequence: 1) Grounding breath (60s) 2) Focus breath (90s) 3) Journaling prompt (30s)
      const sequence = [
        {label:'Grounding — slow belly breaths',time:60,instructions:'Inhale 4s, hold 1s, exhale 6s. Repeat.'},
        {label:'Focus — gentle energizing breaths',time:90,instructions:'Inhale 3s, exhale 3s. Notice any tensions.'},
        {label:'Set an intention — write or reflect',time:30,instructions:'Name a short intention for the next hour.'}
      ];
      if(step>=sequence.length){stepText.textContent='Practice complete. Take a deep breath and return when ready.';timer.textContent='0:00';stopTimers();return}
      const current = sequence[step];
      stepText.textContent = current.label + ' — ' + current.instructions;
      seconds = current.time;
      timer.textContent = formatTime(seconds);
      tId = setInterval(()=>{
        seconds--;
        timer.textContent = formatTime(seconds);
        if(seconds<=0){clearInterval(tId);tId=null;step++;setTimeout(advance,700);} },1000);
    }

    function formatTime(s){const m=Math.floor(s/60);const ss=s%60;return m+':'+(ss<10?'0'+ss:ss)}
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#ffffff;--accent:#758c6a;--muted:#5b6258}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial;background:var(--bg);color:#0b1a12}
    header{display:flex;align-items:center;justify-content:space-between;padding:14px 20px;border-bottom:1px solid #eef6ee}
    .brand{display:flex;gap:12px;align-items:center}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    main{max-width:920px;margin:28px auto;padding:18px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .card{background:white;border-radius:12px;padding:18px;box-shadow:0 10px 30px rgba(10,12,10,0.03)}
    label{display:block;margin-top:10px;font-weight:600}
    input,select,textarea{width:100%;padding:9px;border-radius:8px;border:1px solid #e6efe6}
    .primary{background:var(--accent);color:white;padding:10px 14px;border-radius:10px;border:0;font-weight:700;margin-top:12px}
    .muted{color:var(--muted)}
    footer{max-width:920px;margin:22px auto;padding:12px;color:var(--muted)}
    @media (max-width:900px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div style="width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,var(--accent),#9fc08b);display:flex;align-items:center;justify-content:center;color:white;font-weight:700">A</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">Simple scent care you can schedule</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Welcome</a>
      <a href="services.html">Sessions</a>
      <a href="blends.html">Blends</a>
      <a href="shop.html">Shop</a>
      <a href="pricing.html">Membership</a>
      <a href="about.html">About</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <div class="grid">
      <div>
        <div class="card">
          <h1 style="margin-top:0">Reserve a session</h1>
          <p class="muted">Bookings are typically 30–60 minutes. Sessions include an intake, a short scent session, and clear at-home guidance that may support your goals.</p>

          <form id="bookingForm">
            <label for="name">Name</label>
            <input id="name" name="name" type="text" required>

            <label for="email">Email</label>
            <input id="email" name="email" type="text" required>

            <label for="type">Session type</label>
            <select id="type" name="type">
              <option value="intro">Intro (30 min) — a short orientation</option>
              <option value="standard">Standard (60 min) — intake + blending</option>
              <option value="follow">Follow-up (30 min) — tune and adjust</option>
            </select>

            <label for="date">Preferred date</label>
            <input id="date" name="date" type="date">

            <label for="notes">Brief notes (allergies, pregnancy, pets)</label>
            <textarea id="notes" name="notes" rows="4"></textarea>

            <button class="primary" type="submit">Request reservation</button>
          </form>

          <div id="msg" style="margin-top:12px;color:var(--muted)"></div>

          <div style="margin-top:14px" class="card">
            <h4 style="margin:0">What to expect</h4>
            <p class="muted" style="margin-top:8px">A short conversation about preferences and contraindications, followed by a curated scent exercise. You will receive a simple dilution guide and suggestions you can use at home.</p>
          </div>
        </div>
      </div>

      <aside>
        <div class="card">
          <h3 style="margin-top:0">Need a quick practice?</h3>
          <p class="muted">Try a short breathing + intention exercise in the browser before your session.</p>
          <button class="primary" id="miniTry">Try it now</button>
          <div style="margin-top:10px;font-size:13px;color:var(--muted)">If you prefer, call <a href="tel:{{PHONE}}">{{PHONE}}</a> to schedule.</div>
        </div>

        <div class="card" style="margin-top:12px">
          <h4 style="margin:0">Safety</h4>
          <p class="muted" style="margin-top:8px">We will ask about pregnancy, medications, and pets. If any serious concerns arise we may suggest consulting another provider before using certain essential oils.</p>
        </div>
      </aside>
    </div>
  </main>

  <footer>
    <div class="muted">For urgent questions email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</div>
  </footer>

  <!-- Booking form + small guided modal -->
  <div id="miniModal" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,0.45);align-items:center;justify-content:center;padding:20px">
    <div style="max-width:520px;background:white;padding:18px;border-radius:12px">
      <h3 style="margin-top:0">Three-minute centering</h3>
      <div id="miniBody" style="color:var(--muted);margin-top:8px">We’ll guide you through two short breathing cycles and a one-line intention. Comfortable seated is fine.</div>
      <div style="margin-top:12px;display:flex;gap:8px;align-items:center">
        <button class="primary" id="miniStart">Start</button>
        <button id="miniClose" style="padding:8px;border-radius:8px;border:1px solid #e6efe6;background:white">Close</button>
      </div>
      <div id="miniProgress" style="margin-top:12px;display:none">
        <div id="miniStep" style="font-weight:700"></div>
        <div id="miniTimer" style="color:var(--muted);margin-top:6px"></div>
      </div>
    </div>
  </div>

  <script>
    // Booking form: basic client-side flow (no back-end)
    const form = document.getElementById('bookingForm');
    const msg = document.getElementById('msg');
    form.addEventListener('submit', (e)=>{
      e.preventDefault();
      const data = new FormData(form);
      msg.textContent = 'Thanks — we received your request. We will follow up to confirm. (This is a demo submission.)';
      form.reset();
    });

    // Mini guided modal logic
    const miniModal = document.getElementById('miniModal');
    const miniTry = document.getElementById('miniTry');
    const miniClose = document.getElementById('miniClose');
    const miniStart = document.getElementById('miniStart');
    const miniProgress = document.getElementById('miniProgress');
    const miniStep = document.getElementById('miniStep');
    const miniTimer = document.getElementById('miniTimer');

    miniTry.addEventListener('click', ()=>{miniModal.style.display='flex';});
    miniClose.addEventListener('click', ()=>{miniModal.style.display='none';stopMini();});

    let mid=null, mstep=0, msecs=0;
    function stopMini(){clearInterval(mid);mid=null;miniProgress.style.display='none';miniStart.disabled=false;}

    miniStart.addEventListener('click', ()=>{miniStart.disabled=true;miniProgress.style.display='block';mstep=0;runMini();});

    function runMini(){
      const seq=[{label:'Slow grounding breaths',time:45},{label:'Light focus breaths',time:60},{label:'One-line intention',time:15}];
      if(mstep>=seq.length){miniStep.textContent='Complete — thank you.';miniTimer.textContent='0:00';stopMini();return}
      const cur=seq[mstep];msecs=cur.time;miniStep.textContent=cur.label;miniTimer.textContent=format(msecs);
      mid=setInterval(()=>{msecs--;miniTimer.textContent=format(msecs);if(msecs<=0){clearInterval(mid);mid=null;mstep++;setTimeout(runMini,600);} },1000);
    }
    function format(s){const m=Math.floor(s/60);const ss=s%60;return m+':'+(ss<10?'0'+ss:ss)}
  </script>
